MASCOT='''<svg class="mufid-bird" viewBox="0 0 240 240" role="img" aria-label="Mufid"><circle cx="120" cy="120" r="108" fill="#e7ecdc"/><path d="M18 184 Q120 130 223 181" fill="none" stroke="#c8d4bd" stroke-width="2"/><path d="M62 201 Q90 165 120 171 Q163 161 185 199" fill="#254c3b"/><path d="M79 161 Q49 129 72 83 Q85 57 120 59 Q161 52 177 87 Q193 127 163 163 Q124 190 79 161" fill="#f3e5c6"/><path d="M75 100 Q65 61 104 54 L96 28 L127 52 L142 31 L153 61 Q178 69 179 102 Q159 80 140 91 Q120 108 101 91 Q86 85 75 100" fill="#b87d42"/><path d="M91 109 Q98 100 105 109 M140 109 Q147 100 154 109" stroke="#254c3b" stroke-width="5" stroke-linecap="round" fill="none"/><path d="M112 121 L133 121 L122 136Z" fill="#c98f46"/><path d="M91 150 Q122 172 151 149" fill="none" stroke="#b87d42" stroke-width="3" stroke-linecap="round"/><path d="M75 172 L109 184 L91 202 M166 171 L135 184 L151 201" fill="#3a6b50"/><circle cx="119" cy="194" r="17" fill="#d9b56d"/><path d="M119 182 L125 199 L113 199Z" fill="#254c3b"/><path d="M174 57 Q195 25 214 42 Q207 64 174 57" fill="#658365"/><path d="M176 56 L204 43" stroke="#e7ecdc" stroke-width="2"/></svg>'''

def build():
    rows=[]
    for lang,c in COPY.items():
        c.update(UI[lang])
        c['unavailable']=c['connect_first']
        c['unauthorized']=c['connect_first']
    for lang,c in COPY.items():
        folder=ROOT/'docs'/('' if lang=='ar' else lang)
        # Search shell is already analytics-free and uses the approved edition chrome.
        page=(folder/'search/index.html').read_text()
        page=re.sub(r'<script id="search-copy".*?</script>','',page,flags=re.S)
        page=re.sub(r'<script[^>]*src="[^"]*site-search\.js[^>]*></script>','',page)
        page=re.sub(r'<link[^>]*href="[^"]*/search\.css[^>]*>','',page)
        page=re.sub(r'<title>.*?</title>',f'<title>{c["title"]} | Sayd</title>',page,flags=re.S)
        page=re.sub(r'<!-- seo:start -->.*?<!-- seo:end -->','',page,flags=re.S)
        choices=''.join(f'<button type="button" data-mode="{mode}" aria-pressed="{str(mode=="search").lower()}">{c[mode]}</button>' for mode in ('search','understand','plan'))
        main=f'''<main id="content" class="page-main mufid-page" data-mufid-language="{lang}"><div class="container mufid-shell">
<section class="mufid-access" id="mufid-access"><details class="mufid-settings" open><summary>{c['access']}</summary><p>{c['access_note']}</p><label for="mufid-token">{c['token']}</label><div class="mufid-login"><input id="mufid-token" type="password" autocomplete="off" dir="ltr" spellcheck="false"><button type="button" id="mufid-show" aria-pressed="false">{c['show']}</button><button type="button" id="mufid-connect">{c['save']}</button></div><label class="mufid-endpoint-label" for="mufid-endpoint">{c['endpoint']}</label><input id="mufid-endpoint" type="url" value="https://sayd-mufid-internal.unionmedia-sarl.workers.dev" autocomplete="off" dir="ltr"></details><p id="mufid-connection" role="status" hidden></p></section>
<header class="mufid-hero"><div><span class="mufid-eyebrow">{c['eyebrow']} · SAYD</span><h1>{c['hello']}</h1><p>{c['intro']}</p><small>{c['promise']}</small></div>{MASCOT}</header>
<div class="mufid-workspace"><div class="mufid-starts" role="group" aria-label="{c['title']}">{choices}</div>
<form id="mufid-form"><label class="sr-label" for="mufid-query">{c['query']}</label><textarea id="mufid-query" placeholder="{c['query_hint']}" maxlength="900" rows="3" required aria-describedby="mufid-privacy"></textarea>
<div class="mufid-trip" id="mufid-trip" hidden><div><label for="mufid-destination">{c['destination']}</label><input id="mufid-destination" maxlength="100" autocomplete="off"></div><div><label for="mufid-origin">{c['origin']}</label><input id="mufid-origin" maxlength="100" autocomplete="off"></div><div><label for="mufid-date">{c['date']}</label><input id="mufid-date" type="date"></div><div><label for="mufid-effort">{c['effort']}</label><select id="mufid-effort"><option>{c['light']}</option><option>{c['moderate']}</option><option>{c['active']}</option></select></div><p>{c['trip_note']}</p></div>
<label class="mufid-check"><input type="checkbox" id="mufid-fresh">{c['fresh']}</label><label class="mufid-check" id="mufid-consent-row" hidden><input type="checkbox" id="mufid-consent">{c['consent']}</label><div class="mufid-actions"><button type="submit">{c['submit']} <span aria-hidden="true">↗</span></button><button type="button" data-mode="verify" aria-pressed="false">{c['verify']}</button></div></form>
<div class="mufid-examples"><small>{c['examples']}</small>{''.join(f'<button type="button" data-example="{i}">{c["sample"+str(i)]}</button>' for i in (1,2,3))}</div>
<p id="mufid-status" role="status" aria-live="polite">{c['ready']}</p></div>
<section class="mufid-answer-wrap" id="mufid-answer-wrap" hidden><div class="mufid-section-head"><h2>{c['result']}</h2><button id="mufid-copy-answer" type="button">{c['copy']}</button></div><section id="mufid-answer" hidden aria-live="polite"></section><div id="mufid-sources"></div></section>
<section id="mufid-extras" class="mufid-extras" hidden><h2>{c['trip_tools']}</h2><div class="mufid-extra-grid"><button type="button" data-extra="weather">{c['weather']}</button><button type="button" data-extra="wildlife">{c['wildlife']}</button><button type="button" data-extra="packing">{c['packing']}</button><a data-map="route" target="_blank" rel="noopener noreferrer">{c['route']}</a><a data-map="restaurants" target="_blank" rel="noopener noreferrer">{c['restaurants']}</a><a data-map="hotels" target="_blank" rel="noopener noreferrer">{c['hotels']}</a><a data-map="car" target="_blank" rel="noopener noreferrer">{c['car']}</a><a data-map="photos" target="_blank" rel="noopener noreferrer">{c['photos']}</a></div><p>{c['tool_note']}</p><div id="mufid-extra-answer" aria-live="polite"></div></section>
<div id="mufid-results"></div><footer class="mufid-footer"><p class="mufid-note" id="mufid-privacy">{c['privacy']}</p><div><button type="button" data-mode="suggest" aria-pressed="false">{c['suggest_link']}</button><button type="button" id="mufid-clear">{c['disconnect']}</button><a href="https://sayd-magazine.com/{'' if lang=='ar' else lang+'/'}">{c['browse']} ↗</a></div></footer>
<noscript>{c['nojs']}</noscript></div></main>'''
        page=re.sub(r'<main\b[^>]*>.*?</main>',lambda _:main,page,count=1,flags=re.S)
        canonical='https://sayd-magazine.com/'+('' if lang=='ar' else lang+'/')+'mufid/'
        metadata=f'<link rel="canonical" href="{canonical}"><meta property="og:title" content="{html.escape(c["title"],quote=True)}"><meta name="description" content="{html.escape(c["intro"],quote=True)}">'
        page=page.replace('</head>',metadata+'<link rel="stylesheet" href="'+('../../' if lang!='ar' else '../')+'assets/css/mufid.css?v=1">\n</head>')
        page=page.replace('</body>','<script type="application/json" id="mufid-copy">'+json.dumps(c,ensure_ascii=False).replace('<','\\u003c')+'</script><script src="'+('../../' if lang!='ar' else '../')+'assets/js/mufid.js?v=1" defer></script></body>')
        # Utility language links lead to the corresponding Mufid page.
        page=re.sub(r'<nav class="lang-switch".*?</nav>',lambda m:m[0].replace('/search/','/mufid/'),page,flags=re.S)
        target=folder/'mufid/index.html';target.parent.mkdir(parents=True,exist_ok=True)
        from build_site_search import links
        target.write_text(links(page,target))
        data=json.loads((ROOT/f'docs/assets/search/index-{lang}.json').read_text())
        for a in data['articles']:
            # An explicit article schema prevents internal files/metadata entering the bundle.
            assert re.fullmatch(r'/(?:en/|fr/)?posts/[^/]+/',a['url'])
            rows.append({k:a[k] for k in ('url','title','body','keywords','date','category','image','excerpt')} | {'lang':lang})
    for kind in ('css','js'):
        shutil.copyfile(ROOT/f'assets/{kind}/mufid.{kind}',ROOT/f'docs/assets/{kind}/mufid.{kind}')
    target=ROOT/'services/mufid/data/public-index.json';target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(json.dumps({'version':1,'articles':rows},ensure_ascii=False,separators=(',',':'))+'\n')
    preview={}
    css=(ROOT/'assets/css/mufid.css').read_text()
    js=(ROOT/'assets/js/mufid.js').read_text()
    # Worker preview links point to published Sayd articles, never Worker paths.
    js=js.replace('new URL(value,location.origin)', "new URL(value,'https://sayd-magazine.com')").replace('u.origin!==location.origin', "u.origin!=='https://sayd-magazine.com'")
    js=js.replace('img.src=a.image', "img.src='https://sayd-magazine.com'+a.image")
    js=js.replace("let mode='search',endpoint='',token=''", "let mode='search',endpoint=location.origin,token=''")
    preview['/pilot.js']=js
    preview['/pilot.css']='*{box-sizing:border-box}body{margin:0;background:#fafbf7;color:#20362a;font:17px/1.7 system-ui,sans-serif}.container{margin:auto;padding-inline:20px}nav{padding:12px 20px;background:#244b35;color:white}nav a{color:white;margin-inline:10px}'+css
    for lang,c in COPY.items():
        page=(ROOT/'docs'/('' if lang=='ar' else lang)/'mufid/index.html').read_text()
        main=re.search(r'<main\b[^>]*>.*?</main>',page,re.S)[0]
        # Access is intentionally first in the pilot UI.
        main=main.replace('id="mufid-endpoint" type="url"', 'id="mufid-endpoint" value="https://sayd-mufid-internal.unionmedia-sarl.workers.dev" type="url"')
        copy=json.dumps(c,ensure_ascii=False).replace('<','\\u003c')
        nav='<nav class="mufid-language" aria-label="Language"><span>SAYD / MUFID</span><a href="/">العربية</a><a href="/en/">English</a><a href="/fr/">Français</a></nav>'
        preview['/' if lang=='ar' else '/'+lang+'/']=f'<!doctype html><html lang="{lang}" dir="{"rtl" if lang=="ar" else "ltr"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{html.escape(c["title"])}</title><link rel="stylesheet" href="/pilot.css"></head><body>{nav}{main}<script type="application/json" id="mufid-copy">{copy}</script><script src="/pilot.js" defer></script></body></html>'
    (ROOT/'services/mufid/data/preview.json').write_text(json.dumps(preview,ensure_ascii=False))
    print(f'Mufid pilot: 3 pages, {len(rows)} public language records. No live entry points changed.')
if __name__=='__main__':build()
